1	// Reads the event(s) a page declares about itself in embedded schema.org
2	// JSON-LD — the strongest machine-readable signal, since most event pages
3	// publish it for search engines.
4	//
5	// This is a HELPER, not a pipeline extractor: it's a reusable reader that any
6	// extractor may call (a per-site source, e.g. eventbrite/meetup, to fill a
7	// field the page only states in JSON-LD; or the unsupported-site extractor, to
8	// produce a best-effort event). It never decides whether a page is supported,
9	// and nothing "merges" it behind a source's back — a source asks for it
10	// explicitly. Keeping it a helper is what lets sources stay self-contained
11	// without each reimplementing JSON-LD parsing.
12	//
13	// Expected HTML input — one or more script blocks anywhere in the page:
14	//
15	//   <script type="application/ld+json">
16	//   { "@type": "Event",                          // or MusicEvent, etc.
17	//     "name": "Concert",
18	//     "startDate": "2026-07-01T20:00:00+02:00",
19	//     "endDate":   "2026-07-01T23:00:00+02:00",
20	//     "location": { "@type": "Place", "name": "Blue Note",
21	//                   "address": { "streetAddress": "...", ... } },
22	//     "description": "<p>may contain HTML</p>" }
23	//   </script>
24	//
25	// Event objects may also be nested inside arrays, "@graph", or
26	// "itemListElement" wrappers; find() collects them all, in document order.
27	//
28	// Field mapping: title/start/end/description come straight from the
29	// name/startDate/endDate/description properties (description rendered to text,
30	// keeping its <br>/newline layout); location flattens Place name + PostalAddress
31	// parts into one comma-separated string.
32	//
33	// Uses GCal.clean / normalizeDateValue / htmlToText / parts at call time.
34	// Augments globalThis.GCal (never replaces it) so load order can't clobber
35	// another file's contributions.
36	globalThis.GCal = Object.assign(globalThis.GCal || {}, (() => {
37	  function find() {
38	    const found = [];
39	    const visit = (node) => {
40	      if (!node) return;
41	      if (Array.isArray(node)) return node.forEach(visit);
42	      if (typeof node !== "object") return;
43	      const types = [].concat(node["@type"] || []);
44	      if (types.some((t) => typeof t === "string" && /event$/i.test(t))) found.push(node);
45	      visit(node["@graph"]);
46	      visit(node.subEvent);
47	      if (Array.isArray(node.itemListElement)) {
48	        visit(node.itemListElement.map((it) => (it && it.item) || it));
49	      }
50	    };
51	    for (const script of document.querySelectorAll('script[type="application/ld+json"]')) {
52	      const parsed = parseLd(script.textContent);
53	      if (parsed !== undefined) visit(parsed);
54	    }
55	    return found;
56	  }
57	
58	  // Parse a JSON-LD block, tolerating the single most common real-world defect:
59	  // RAW (unescaped) control characters — literal newlines, tabs, carriage
60	  // returns — sitting inside a string value. The JSON spec forbids them, but
61	  // server-side templating that drops a multi-line description straight into a
62	  // schema.org "description" emits them anyway (seen on ASP.NET/SharePoint and
63	  // hand-built CMSes), which makes a strict JSON.parse throw and silently
64	  // discards an otherwise-perfectly-good Event. So on a parse failure, escape
65	  // only the control characters that appear INSIDE strings and retry once —
66	  // this rewrites nothing structural (control chars between tokens are already
67	  // valid whitespace and are left untouched) and never fabricates data. Returns
68	  // undefined when even the salvaged text won't parse.
69	  function parseLd(text) {
70	    try {
71	      return JSON.parse(text);
72	    } catch (e) {
73	      try {
74	        return JSON.parse(escapeControlCharsInStrings(text));
75	      } catch (e2) {
76	        return undefined;
77	      }
78	    }
79	  }
80	
81	  // Escape raw control characters (code point < 0x20) that occur inside a JSON
82	  // string literal, leaving everything else — including whitespace between
83	  // tokens — byte-for-byte identical. Tracks string/escape state so a control
84	  // char outside a string (structural whitespace) is not rewritten.
85	  function escapeControlCharsInStrings(text) {
86	    let out = "";
87	    let inStr = false;
88	    let escaped = false;
89	    for (let i = 0; i < text.length; i++) {
90	      const ch = text[i];
91	      if (!inStr) {
92	        out += ch;
93	        if (ch === '"') inStr = true;
94	        continue;
95	      }
96	      if (escaped) {
97	        out += ch;
98	        escaped = false;
99	        continue;
100	      }
101	      if (ch === "\\") {
102	        out += ch;
103	        escaped = true;
104	        continue;
105	      }
106	      if (ch === '"') {
107	        out += ch;
108	        inStr = false;
109	        continue;
110	      }
111	      const code = text.charCodeAt(i);
112	      if (code < 0x20) {
113	        if (ch === "\n") out += "\\n";
114	        else if (ch === "\r") out += "\\r";
115	        else if (ch === "\t") out += "\\t";
116	        else out += "\\u" + code.toString(16).padStart(4, "0");
117	        continue;
118	      }
119	      out += ch;
120	    }
121	    return out;
122	  }
123	
124	  // `dayFirst` (default false) is forwarded to normalizeDateValue so a non-ISO
125	  // startDate/endDate written as an ambiguous DD/MM/YYYY slash date (which
126	  // schema.org shouldn't carry, but non-US sites emit anyway) is read day-first
127	  // when the caller knows the page's locale is day-first.
128	  function toEvent(ld, dayFirst) {
129	    if (!ld) return {};
130	    return {
131	      title: GCal.clean(ld.name),
132	      start: GCal.normalizeDateValue(ld.startDate, dayFirst),
133	      end: GCal.normalizeDateValue(ld.endDate, dayFirst),
134	      location: flattenLocation(ld.location),
135	      // Render the (possibly HTML) description preserving its <br>/newline
136	      // layout, rather than collapsing it to a single line.
137	      description: GCal.htmlToText(ld.description),
138	    };
139	  }
140	
141	  // Flatten a schema.org location (Place + PostalAddress) into one
142	  // comma-separated string. De-dup by substring, since sites often repeat the
143	  // city/state inside streetAddress (Meetup puts "96 Wythe Ave, Brooklyn, NY"
144	  // there AND fills addressLocality/Region): skip any part already contained in
145	  // one we've kept.
146	  function flattenLocation(loc) {
147	    if (!loc) return "";
148	    if (Array.isArray(loc)) loc = loc[0];
149	    if (typeof loc === "string") return GCal.clean(loc);
150	    const addr = loc.address;
151	    // Some sites put the venue's whole formatted postal address into Place.name
152	    // AND repeat the pieces in `address`. When the name already spells out both
153	    // the city and the street, it's a complete address on its own — appending
154	    // the parsed parts only duplicates them and tacks on noise (the district),
155	    // so use the name verbatim, the way a dedicated source reads it.
156	    if (nameIsFullAddress(loc.name, addr)) return GCal.clean(loc.name);
157	    const p = GCal.parts((cand, kept) => kept.toLowerCase().includes(cand.toLowerCase()));
158	    p.add(loc.name);
159	    if (typeof addr === "string") {
160	      p.add(addr);
161	    } else if (addr && typeof addr === "object") {
162	      p.add(addr.streetAddress).add(addr.addressLocality).add(addr.addressRegion).add(addr.postalCode);
163	      // A country code after a region is noise ("..., NY, us"), and so is a
164	      // country bolted straight onto a street whose city the address left out:
165	      // "Bialik Street 27, Israel" skips a level of the hierarchy and names no
166	      // findable place, which is why a dedicated source writes the street alone.
167	      // So append the country only when nothing finer already stands in for it —
168	      // no region, and either the address named its city or it gave no street at
169	      // all (leaving the country the most specific thing we have).
170	      const skipsCity = GCal.clean(addr.streetAddress) && !GCal.clean(addr.addressLocality);
171	      if (!addr.addressRegion && !skipsCity) p.add(countryName(addr.addressCountry));
172	    }
173	    return p.join();
174	  }
175	
176	  // Whether Place.name is ITSELF the full formatted address — a comma-separated
177	  // string that already contains both the city (addressLocality) and the street
178	  // (streetAddress with its house number removed, since the name may reorder or
179	  // drop the number). Only then is re-composing the structured parts redundant.
180	  // Requiring BOTH the city and a substantive (≥4 char) street core keeps a
181	  // venue merely named after its city ("Zappa Tel Aviv", street elsewhere) from
182	  // qualifying, so its street is still composed in.
183	  function nameIsFullAddress(name, addr) {
184	    if (!addr || typeof addr !== "object") return false;
185	    const hay = GCal.clean(name).toLowerCase();
186	    if (!hay.includes(",")) return false;
187	    const locality = GCal.clean(addr.addressLocality).toLowerCase();
188	    const streetCore = GCal.clean(String(addr.streetAddress || "").replace(/\d+/g, " ")).toLowerCase();
189	    if (!locality || streetCore.length < 4) return false;
190	    return hay.includes(locality) && hay.includes(streetCore);
191	  }
192	
193	  // schema.org allows addressCountry to be a plain string OR a Country object
194	  // ({ "@type": "Country", "name": "..." }, seen on livenation.de) — read the
195	  // name out of either shape so an object doesn't stringify to "[object
196	  // Object]". A short code held in the object form ("US") is dropped as
197	  // noise, the same convention custom/livenation.js already applies locally
198	  // for this exact shape; a plain-string code is passed through unchanged
199	  // (sites publish those directly, and existing sources rely on seeing it).
200	  function countryName(v) {
201	    if (typeof v === "string") return v;
202	    if (v && typeof v.name === "string") return v.name.length > 2 ? v.name : "";
203	    return "";
204	  }
205	
206	  return { embeddedEvents: { find, toEvent } };
207	})());
