1	// THE CORE GENERIC EXTRACTOR — the one extractor that runs on every page,
2	// whatever its host. It scrapes a best-effort event from any page's own
3	// self-description, and it is the BASE LAYER of the whole pipeline:
4	//   - on a host with no per-site source, it is the only extractor, and the popup
5	//     shows its event as a calendar button when it's complete enough (title +
6	//     location + start) and the host isn't denylisted, otherwise/also using it to
7	//     pre-fill the "request this source" form (events-popup/popup.js's chooseContent);
8	//   - on a supported host, assemble-events.js runs it FIRST and merges the site's
9	//     source over it, so a per-site extractor only has to state the fields this
10	//     one gets wrong (event-extractors/custom/<site>.js);
11	//   - on a supported host with no per-site source, it IS the site's support —
12	//     such a site is fully supported (supportedDomains lists it) with no
13	//     extractor file of its own.
14	//
15	// It sits beside the registry and the orchestrator rather than under custom/:
16	// that folder is the extensibility point, one file per site, and this is a
17	// different thing — the one fixed, site-agnostic reader every one of those files
18	// layers over. Nothing here may know about a specific site.
19	//
20	// extract() returns an array of the page's best-effort events (empty when the
21	// page describes none), which assemble-events.js normalizes and presents. It
22	// combines two best-effort signals, first non-empty value per field winning:
23	//   1. events the page embeds about itself (GCal.embeddedEvents — schema.org)
24	//   2. generic heuristics over the page's meta tags, microdata, <time>, and text
25	//
26	// Generic heuristics, each tried against progressively weaker signals:
27	//   title       og:title meta tag -> the page's <h1> -> document title
28	//   start/end   microdata (itemprop="startDate"/"endDate", on <meta> or
29	//               <time> elements) -> event:start_time/end_time meta tags ->
30	//               the first <time datetime="..."> on the page -> the first
31	//               date-and-time pattern in the page's visible text
32	//               ("June 14, 2026 at 7 PM", "14 June 2026", "6/14/2026", ISO)
33	//   location    itemprop="location" -> <address> -> the first reasonably
34	//               short element whose class/id mentions "venue" or "location" ->
35	//               OG place/business/geo meta tags -> the "@ Venue" title tail ->
36	//               an "(Online)"-style title parenthetical -> the street address
37	//               in the page's footer/header chrome (single-venue sites);
38	//               whatever won is then UPGRADED to the fuller address the page's
39	//               own "open in maps" link spells out, when that link's text leads
40	//               with the venue we already have (upgradeLocation)
41	//   description og:description or description meta tag ->
42	//               itemprop="description" (line breaks preserved)
43	//   all-day     a start–end pair covering whole calendar days (00:00 -> 23:59)
44	//               is the all-day convention, collapsed to the date-only form
45	//               (helpers/dates.js's allDayRange)
46	//   ctz         derived only when two independent page-declared hints agree (a
47	//               stated inline-JSON timezone, the events' own UTC offsets, the
48	//               JSON-LD venue country, the page locale) — see
49	//               helpers/derive-timezone.js (#674); otherwise absent
50	(() => {
51	  const { clean, text, meta, blockText, htmlToText, bodyText, normalizeDateValue, parseDateFromText, endFromTimeRange, allDayRange, merge, embeddedEvents, parts, deriveCtz } = GCal;
52	
53	  // How much of the page's body text the date/time scan below considers. Large
54	  // enough to reach past a long nav/menu block (e.g. a WordPress mega-menu)
55	  // that sits before the real content on some sites, small enough to stay a
56	  // deliberate "near the top of the page" heuristic rather than a full-page scan.
57	  const BODY_TEXT_SCAN_LIMIT = 16000;
58	
59	  function extract() {
60	    const embedded = embeddedEvents.find();
61	    // Ambiguous numeric dates ("05/07/2026") are read day-first when the page
62	    // declares a non-US locale — the DD/MM/YYYY convention most of the world
63	    // (and every non-US site here) writes, in both JSON-LD and visible text.
64	    const dayFirst = pageUsesDayFirstDates();
65	    // Several embedded events => a listing page; surface each.
66	    if (embedded.length > 1) return collapseAllDay(withCtz(embedded.map((ld) => embeddedEvents.toEvent(ld, dayFirst)).map(trimVenueTitle)));
67	
68	    const event = trimVenueTitle(upgradeLocation(merge(embeddedEvents.toEvent(embedded[0], dayFirst), heuristics(dayFirst))));
69	    // The heuristics always fill a title (og:title -> <h1> -> document title),
70	    // present on essentially every page, so a title alone is not an event. Treat
71	    // this as an event only when the page embedded one or a date was parsed.
72	    return embedded.length > 0 || event.start ? collapseAllDay(withCtz([event])) : [];
73	  }
74	
75	  // Rewrite any event whose start–end pair spans whole calendar days
76	  // (00:00 → 23:59, helpers/dates.js's allDayRange) into the date-only all-day
77	  // form the string contract uses. Runs last, over the finished events, so it
78	  // sees the merged start/end whichever signal supplied them — and after
79	  // withCtz, since a floating midnight carries no offset hint for deriveCtz to
80	  // read either way.
81	  function collapseAllDay(events) {
82	    for (const e of events) {
83	      const range = allDayRange(e.start, e.end);
84	      if (range) {
85	        e.start = range.start;
86	        e.end = range.end;
87	      }
88	    }
89	    return events;
90	  }
91	
92	  // Whether the page's own declared locale is a day-first one (DD/MM/YYYY) — the
93	  // everyday format outside the US, so an ambiguous numeric slash date should be
94	  // read day-first (see helpers/dates.js). Conservative: only a POSITIVE non-US
95	  // locale signal flips it — an explicit region that isn't US (he-IL, en-GB, …)
96	  // or a non-English language; a bare "en" (region unknown) keeps the safe
97	  // month-first default rather than guessing. Mirrors derive-timezone.js's read
98	  // of <html lang> / og:locale.
99	  function pageUsesDayFirstDates() {
100	    const MONTH_FIRST_REGIONS = new Set(["US"]);
101	    const langAttr = document.documentElement ? document.documentElement.getAttribute("lang") : "";
102	    for (const raw of [langAttr, meta("og:locale")]) {
103	      const m = /^([a-z]{2,3})(?:[-_]([a-z]{2}))?/i.exec(clean(raw));
104	      if (!m) continue;
105	      const region = (m[2] || "").toUpperCase();
106	      if (region) return !MONTH_FIRST_REGIONS.has(region);
107	      if (m[1].toLowerCase() !== "en") return true;
108	    }
109	    return false;
110	  }
111	
112	  // The one field the heuristics can never scrape directly: the event's
113	  // timezone. deriveCtz (helpers/derive-timezone.js) answers only when two
114	  // independent page-declared hints agree; a "" answer leaves the events
115	  // exactly as before (#674). Page-level on purpose: every event on the page
116	  // shares the one corroborated zone, and a page whose events span zones never
117	  // gets one (the offset/country unanimity rules see to it).
118	  function withCtz(events) {
119	    const ctz = deriveCtz(events.flatMap((e) => [e.start, e.end]));
120	    if (ctz) for (const e of events) e.ctz = ctz;
121	    return events;
122	  }
123	
124	  // "Event @ Venue" titles (bandsintown, Songkick, and many music/ticketing
125	  // listings — whether the title arrives via JSON-LD or og:title) repeat the venue
126	  // in the title. When a FULLER location is known — one that leads with that same
127	  // venue but carries more (street, city, country) — the "@ Venue" tail is
128	  // redundant, so trim the title to the event name alone, the way a dedicated
129	  // source reads it. Guarded to a strict superset (the location starts with the
130	  // venue but is longer) so we only strip when the venue is known independently: a
131	  // location that is exactly the title's tail (e.g. one parsed back out of the
132	  // title by venueFromTitle) leaves the title untouched.
133	  function trimVenueTitle(event) {
134	    if (!event || !event.title) return event;
135	    const at = event.title.indexOf(" @ ");
136	    if (at < 0) return event;
137	    const venueTail = clean(event.title.slice(at + 3));
138	    const loc = clean(event.location);
139	    if (venueTail && loc && loc !== venueTail && loc.startsWith(venueTail)) {
140	      event.title = clean(event.title.slice(0, at));
141	    }
142	    return event;
143	  }
144	
145	  // Replace the event's location with the fuller form the page's own maps link
146	  // spells out, when there is one. A schema.org Place is routinely published with
147	  // the venue's NAME and an empty address, while the same page links that venue
148	  // to a maps service using its full address as the link's own text ("Blue Note,
149	  // 131 W 3rd St, New York") — the "open in maps" convention (the same
150	  // page-declared marker chromeAddress() already trusts in a site's footer, but
151	  // here it marks THIS event's venue). See mapsLinkAddress for the guard.
152	  function upgradeLocation(event) {
153	    const fuller = mapsLinkAddress(event.location);
154	    if (fuller) event.location = fuller;
155	    return event;
156	  }
157	
158	  // The first maps-service link whose own text is `location` SPELLED OUT: it
159	  // leads with exactly the location we already have and continues past a comma
160	  // into the rest of the address. That strict-superset guard (the one
161	  // trimVenueTitle uses) is what keeps this an upgrade rather than a second
162	  // opinion — a maps link pointing somewhere else on the page (a box office, the
163	  // operator's own office, another venue) never replaces the event's location,
164	  // and neither does a venue that merely shares a prefix ("Blue Note Cafe"). The
165	  // candidate must still read like an address (addressText/looksLikeAddress), so
166	  // a bare "Get directions" call to action never qualifies.
167	  function mapsLinkAddress(location) {
168	    const loc = clean(location);
169	    if (!loc) return "";
170	    for (const a of document.querySelectorAll("a[href]")) {
171	      if (!MAPS_SERVICE.test(a.getAttribute("href") || "")) continue;
172	      const address = addressText(a);
173	      if (address.startsWith(loc) && /^\s*,/.test(address.slice(loc.length))) return address;
174	    }
175	    return "";
176	  }
177	
178	  // Best-effort scrape of any page's meta tags / microdata / text. `dayFirst`
179	  // (see extract) is forwarded to every date parse so an ambiguous numeric slash
180	  // date is read day-first on a non-US-locale page.
181	  function heuristics(dayFirst) {
182	    const out = {};
183	
184	    out.title = stripSiteSuffix(meta("og:title")) || text("h1") || clean(document.title);
185	
186	    const startProp = document.querySelector('[itemprop="startDate"]');
187	    if (startProp) {
188	      out.start = normalizeDateValue(
189	        startProp.getAttribute("content") || startProp.getAttribute("datetime") || startProp.textContent,
190	        dayFirst
191	      );
192	    }
193	    const endProp = document.querySelector('[itemprop="endDate"]');
194	    if (endProp) {
195	      out.end = normalizeDateValue(
196	        endProp.getAttribute("content") || endProp.getAttribute("datetime") || endProp.textContent,
197	        dayFirst
198	      );
199	    }
200	    if (!out.start) {
201	      out.start = meta("event:start_time");
202	      out.end = out.end || meta("event:end_time");
203	    }
204	    if (!out.start) {
205	      const timeEl = document.querySelector("time[datetime]");
206	      if (timeEl) out.start = normalizeDateValue(timeEl.getAttribute("datetime"), dayFirst);
207	    }
208	    if (!out.start) {
209	      const body = bodyText().slice(0, BODY_TEXT_SCAN_LIMIT);
210	      out.start = parseDateFromText(body, dayFirst);
211	      // A start scraped from text often sits next to its end as a time range
212	      // ("6:30 pm - 10:00 pm"); recover the end when nothing structured gave one.
213	      if (out.start && !out.end) out.end = endFromTimeRange(body, out.start);
214	    } else if (!out.start.includes("T") || /T00:00(?::00)?/.test(out.start)) {
215	      // <time datetime> (or microdata) gave date-only or midnight-UTC — a common
216	      // placeholder pattern. Try metadata descriptions first (curated, one focused
217	      // sentence vs the whole page), then body text, for a timed start on the same
218	      // date; if found, prefer it over the midnight placeholder.
219	      const datePrefix = out.start.slice(0, 10);
220	      const body = bodyText().slice(0, BODY_TEXT_SCAN_LIMIT);
221	      for (const src of [meta("og:description"), meta("description"), body]) {
222	        const refined = parseDateFromText(src, dayFirst);
223	        if (refined && refined.includes("T") && refined.startsWith(datePrefix)) {
224	          out.start = refined;
225	          if (!out.end) out.end = endFromTimeRange(src, out.start);
226	          break;
227	        }
228	      }
229	    }
230	
231	    out.location =
232	      text('[itemprop="location"]') ||
233	      text("address") ||
234	      shortText('[class*="venue" i], [class*="location" i], [id*="location" i]') ||
235	      metaLocation() ||
236	      venueFromTitle(out.title);
237	    // A "(Virtual)", "(Online)", or "(Webinar)" parenthetical in the event title
238	    // signals a virtual event with no physical venue — a convention used by many
239	    // event platforms (EventBrite, Meetup, Luma, …).
240	    if (!out.location && /\((virtual|online|webinar)\)/i.test(out.title || "")) {
241	      out.location = "Online";
242	    }
243	    // Dead last — even the "(Online)" inference above outranks it, because site
244	    // chrome describes the site, not this event.
245	    if (!out.location) out.location = chromeAddress();
246	
247	    // Preserve the description's line breaks. Meta descriptions often contain
248	    // literal HTML markup (e.g. "<br />") rather than real newlines — parse
249	    // them through htmlToText so markup becomes text structure.
250	    const rawDesc = meta("og:description") || meta("description");
251	    out.description = rawDesc ? htmlToText(rawDesc) : blockText('[itemprop="description"]');
252	
253	    return out;
254	  }
255	
256	  // og:title often ends with the site's own name (" - Tel Aviv Cinematheque",
257	  // "… - Think&Drink"); drop that trailing " <sep> <site name>" so the generic
258	  // title is just the event, the way a per-site source would read it. Only the
259	  // exact og:site_name is stripped, so a real title that merely contains a dash
260	  // is left alone.
261	  function stripSiteSuffix(title) {
262	    title = clean(title);
263	    const site = clean(meta("og:site_name"));
264	    if (!title || !site) return title;
265	    for (const sep of [" - ", " | ", " – ", " — "]) {
266	      const suffix = sep + site;
267	      if (title.endsWith(suffix)) return clean(title.slice(0, -suffix.length));
268	    }
269	    return title;
270	  }
271	
272	  // Last-resort location: the place meta tags some pages publish (the Open Graph
273	  // "place"/"business" address fields, or the geo.* tags) when nothing on the
274	  // page exposed a location via microdata, <address>, or a venue/location class.
275	  // Composed into one comma-separated string, most specific part first; the
276	  // coordinate (lat/long) tags are deliberately ignored — they're not a venue.
277	  function metaLocation() {
278	    const p = parts();
279	    p.add(meta("og:title:place") || meta("place:name") || meta("geo.placename"));
280	    p.add(meta("og:street-address") || meta("business:contact_data:street_address"));
281	    p.add(meta("og:locality") || meta("business:contact_data:locality"));
282	    p.add(meta("og:region") || meta("business:contact_data:region") || meta("geo.region"));
283	    p.add(meta("og:postal-code") || meta("business:contact_data:postal_code"));
284	    p.add(meta("og:country-name") || meta("business:contact_data:country_name"));
285	    return p.join();
286	  }
287	
288	  // Last-resort location: many event/listing pages title themselves
289	  // "Event @ Venue" (bandsintown, secrettelaviv, Songkick, …). When nothing more
290	  // structured exposed a location, take the part after the first " @ " in the
291	  // page title as a best-effort venue. Bounded in length so a stray "@" in a
292	  // long title doesn't turn a whole sentence into a location.
293	  function venueFromTitle(title) {
294	    const i = (title || "").indexOf(" @ ");
295	    if (i < 0) return "";
296	    const venue = clean(title.slice(i + 3));
297	    return venue.length <= 80 ? venue : "";
298	  }
299	
300	  // Href of a maps service — a "directions to us" link marks its own text as
301	  // the site's street address.
302	  const MAPS_SERVICE = /(?:maps\.google\.|google\.[a-z.]+\/maps|waze\.com|openstreetmap\.org|maps\.apple\.com|bing\.com\/maps)/i;
303	  // An icon file whose name says "this is where we are" (location.png,
304	  // map-pin.svg, map_marker.webp, …) — the wrapping link's text is the address.
305	  const PIN_ICON = /(?:location|map[-_]?pin|map[-_]?marker)[^/]*\.(?:png|svg|gif|jpe?g|webp|ico)/i;
306	
307	  // Last-resort location: the street address a single-venue site (a club, a
308	  // cinema, a theater) publishes once in its page chrome instead of repeating
309	  // it in every event's details. The footer is scanned first, then the header
310	  // (some venues use a top contact bar). Only deliberate "this is our address"
311	  // markers are read — never arbitrary chrome text — in signal-strength order:
312	  //   1. a maps-service link (Google Maps, Waze, OSM, Apple/Bing Maps)
313	  //   2. an element whose class/id mentions "addres" (covers "address" and the
314	  //      bare "addres" misspelling seen in the wild)
315	  //   3. a link marked by a location-pin icon (PIN_ICON above)
316	  // Each candidate must still read like a street address (looksLikeAddress), so
317	  // "Get Directions" links, phone numbers, and copyright lines never qualify.
318	  // Ranked below every event-specific signal (including the "(Online)" title
319	  // inference): chrome describes the site, so on a multi-venue platform an
320	  // office address in the footer must lose to any per-event location the page
321	  // exposes — platforms publish JSON-LD/meta locations, which win far earlier.
322	  function chromeAddress() {
323	    const markers = [
324	      (root) => [...root.querySelectorAll("a[href]")].filter((a) => MAPS_SERVICE.test(a.getAttribute("href"))),
325	      (root) => root.querySelectorAll('[class*="addres" i], [id*="addres" i]'),
326	      (root) =>
327	        [...root.querySelectorAll("a")].filter((a) =>
328	          [...a.querySelectorAll("img")].some((img) =>
329	            PIN_ICON.test(`${img.getAttribute("src") || ""} ${img.getAttribute("data-src") || ""}`)
330	          )
331	        ),
332	    ];
333	    for (const scope of ['footer, [class*="footer" i], [id*="footer" i]', 'header, [class*="header" i], [id*="header" i]']) {
334	      const roots = document.querySelectorAll(scope);
335	      for (const marked of markers) {
336	        for (const root of roots) {
337	          for (const el of marked(root)) {
338	            const address = addressText(el);
339	            if (address) return withSiteVenue(address);
340	          }
341	        }
342	      }
343	    }
344	    return "";
345	  }
346	
347	  // The candidate's own visible text. In a real (scripting-enabled) Chrome a
348	  // <noscript>'s content is one RAW TEXT node — naive textContent would splice
349	  // image markup into the address (the gcec RULES.md jsdom-vs-Chrome trap
350	  // that bit custom/telavivcinematheque.js) — so noscript/script/style subtrees
351	  // are dropped from a clone before reading. A leading "Address:"-style label
352	  // is dropped too.
353	  function addressText(el) {
354	    const copy = el.cloneNode(true);
355	    for (const n of copy.querySelectorAll("noscript, script, style")) n.remove();
356	    const t = clean(copy.textContent).replace(/^(?:address|כתובת)\s*:\s*/i, "");
357	    return looksLikeAddress(t) ? t : "";
358	  }
359	
360	  // A plausible one-line street address: short, carries a street number, is
361	  // mostly words rather than digits (a phone number is the reverse), and isn't
362	  // an email / URL / copyright line.
363	  function looksLikeAddress(t) {
364	    if (t.length < 5 || t.length > 120) return false;
365	    const letters = (t.match(/\p{L}/gu) || []).length;
366	    const digits = (t.match(/\d/g) || []).length;
367	    if (!digits || letters < 3 || letters < digits) return false;
368	    return !/[@©]|https?:|copyright|all rights reserved|כל הזכויות/i.test(t);
369	  }
370	
371	  // On a single-venue site the site IS the venue, so when the page names itself
372	  // (og:site_name) the venue leads the composed location — "<venue>, <address>"
373	  // — the way a dedicated single-venue source (and a human typing a Calendar
374	  // location) writes it. Skipped when the name already appears in the address,
375	  // or is merely the site's domain ("stubhub.com" is not a venue).
376	  function withSiteVenue(address) {
377	    const site = clean(meta("og:site_name"));
378	    if (!site || address.includes(site) || /^[\w.-]+\.[a-z]{2,}$/i.test(site)) return address;
379	    return `${site}, ${address}`;
380	  }
381	
382	  // First element matching `sel` whose text is plausibly a venue string
383	  // (short, non-empty) rather than a whole section of the page.
384	  function shortText(sel) {
385	    for (const el of document.querySelectorAll(sel)) {
386	      const t = clean(el.textContent);
387	      if (t && t.length >= 3 && t.length <= 140) return t;
388	    }
389	    return "";
390	  }
391	
392	  GCal.genericExtractor = { extract };
393	})();
